import{_ as a,a as o,c as r,ac as i}from"./chunks/framework.BSuaGltH.js";const m=JSON.parse('{"title":"Go 基础复习：用实验回答切片、接口、取消与事务问题","description":"先独立回答，再沿共用正文验证结果；记录解释、边界和项目证据，避免只背面试结论。","frontmatter":{"title":"Go 基础复习：用实验回答切片、接口、取消与事务问题","description":"先独立回答，再沿共用正文验证结果；记录解释、边界和项目证据，避免只背面试结论。","showdocs":{"topics":[{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"排错","scope":"general","audience":"general","group":"语言与开发","summary":"先独立回答，再沿共用正文验证结果；记录解释、边界和项目证据，避免只背面试结论。","status":"active","related":[{"title":"Beego 工程维护：模块、MVC 与排错","link":"/programming/go/plus/ecosystem/base-beego","kind":"开发实践","scope":"general","audience":"general"},{"title":"Gin 与 SQLite · 运行、重启与失败测试","link":"/programming/go/plus/practice/api-part-02","kind":"知识专题","scope":"general","audience":"general"},{"title":"Gin 与 SQLite · 状态机、事务与接口契约","link":"/programming/go/plus/practice/api-part-01","kind":"知识专题","scope":"general","audience":"general"},{"title":"Go 包与模块：导入、导出与依赖方向","link":"/programming/go/base/intermediate/engineering","kind":"知识专题","scope":"general","audience":"general"},{"title":"Go 编码规范：格式、命名、接口与评审","link":"/programming/go/plus/practice/coding_guidelines","kind":"开发实践","scope":"general","audience":"general"}],"prev":{"text":"Go 性能排查：pprof、阻塞与压测复核","link":"/programming/go/plus/troubleshooting/pprof"},"next":{"text":"Go 后端面试复盘：语言、并发与服务实践","link":"/programming/go/pro/interview/golang-interview"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Go 性能排查：pprof、阻塞与压测复核","link":"/programming/go/plus/troubleshooting/pprof"},"next":{"text":"Go 后端面试复盘：语言、并发与服务实践","link":"/programming/go/pro/interview/golang-interview"}},"headers":[],"relativePath":"programming/go/pro/review/review.md","filePath":"programming/go/pro/review/review.md"}'),n={name:"programming/go/pro/review/review.md"};function t(c,e,l,s,d,p){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="go-基础复习-用实验回答切片、接口、取消与事务问题" tabindex="-1">Go 基础复习：用实验回答切片、接口、取消与事务问题 <a class="header-anchor" href="#go-基础复习-用实验回答切片、接口、取消与事务问题" aria-label="Permalink to &quot;Go 基础复习：用实验回答切片、接口、取消与事务问题&quot;">​</a></h1><p>进入 Pro 时先做前三题，分别检查值复制、接口和任务退出。第四题用到数据库，在学完 <a href="/programming/go/plus/practice/api#transaction">Gin/SQLite 事务</a>后再做。每题先写预期，再展开参考解法；答错时只改变一个条件，到对应正文运行例子，找出结果从哪一步开始不同。</p><h2 id="slice-review" tabindex="-1">切片复制是否独立 <a class="header-anchor" href="#slice-review" aria-label="Permalink to &quot;切片复制是否独立 {#slice-review}&quot;">​</a></h2><p>设 <code>a := []int{1, 2, 3}</code>，<code>b := a[:2]</code>。依次执行 <code>b[0] = 9</code>、<code>b = append(b, 8)</code>，原切片的三个元素是什么？重新从 <code>[1, 2, 3]</code> 开始，令 <code>b := a[:2:2]</code> 后重复这两步，原切片第三个元素还会变化吗？<a href="/programming/go/base/basic/slices">切片实验</a></p><details class="details custom-block"><summary>参考解法</summary><p>第一组得到 <code>[9 2 8]</code>。<code>b[0]</code> 与 <code>a[0]</code> 是同一存储位置，追加时 <code>b</code> 的容量仍覆盖 <code>a[2]</code>。另从原始输入开始，<code>a[:2:2]</code> 在追加前仍共享前两个元素，追加时则必须换底层数组，因此第三个元素保持 3。要使元素槽位从一开始就独立，可以 <code>make</code> 后 <code>copy</code>；若元素内部含指针，两份元素仍可指向同一个对象。</p></details><h2 id="nil-review" tabindex="-1">为什么 interface nil 判断失败 <a class="header-anchor" href="#nil-review" aria-label="Permalink to &quot;为什么 interface nil 判断失败 {#nil-review}&quot;">​</a></h2><p>一个实现 <code>error</code> 的 <code>*MyError</code> 指针为 nil。函数把该指针当作 <code>error</code> 返回，调用方的 <code>err == nil</code> 会得到什么？如果成功分支直接返回 <code>nil</code>，哪个判断结果会变化？<a href="/programming/go/base/intermediate/interfaces">接口 nil 实验</a></p><details class="details custom-block"><summary>参考解法</summary><p>接口包含动态类型和动态值。有具体指针类型但值为 nil 的接口，整体仍不为 nil。表示成功时返回字面 nil，而不是携带 nil 指针的 error 接口。预期能说明“具体指针 nil”和“接口 nil”为什么不同；不能靠打印外观判断。</p></details><h2 id="cancel-review" tabindex="-1">context 取消会结束 goroutine 吗 <a class="header-anchor" href="#cancel-review" aria-label="Permalink to &quot;context 取消会结束 goroutine 吗 {#cancel-review}&quot;">​</a></h2><p>消费者处理第一条记录后出错，生产者准备发送第二条。谁通知它停止，谁关闭数据通道，谁在函数返回前检查它已经退出？分别画出“正常读完”和“消费者先退出”的顺序。<a href="/programming/go/base/intermediate/cancellation">取消与完成通知</a></p><details class="details custom-block"><summary>参考解法</summary><p>读完时生产者关闭数据通道，消费者的遍历结束。消费失败时，由共同所有者调用 cancel；阻塞发送处同时监听 <code>ctx.Done()</code> 才能退出。完成通知由生产者在离开时关闭，调用方收到它再返回业务错误。可对照<a href="/programming/go/pro/interview/golang-interview#_29-5-生产者消费者安全关闭">生产者消费者模板</a>。这项判断不依赖 sleep，也不等同于已撤销先前的业务副作用。</p></details><h2 id="transaction-review" tabindex="-1">事务失败时哪些数据应该回滚 <a class="header-anchor" href="#transaction-review" aria-label="Permalink to &quot;事务失败时哪些数据应该回滚 {#transaction-review}&quot;">​</a></h2><p>更新任务状态与写入状态变更记录属于一个业务操作。若 <code>UPDATE tasks</code> 成功，<code>INSERT changes</code> 失败，接口之后再查任务和历史，各自应看到什么？<code>records</code> 保存的是学习心得，与本次事务无关。<a href="/programming/go/plus/practice/api#transaction">项目事务测试</a></p><details class="details custom-block"><summary>参考解法</summary><p>更新 tasks 与插入 changes 应在同一事务内完成，两步都成功才提交。项目中的 <code>TestStatusRollback</code> 用临时触发器让插入失败；客户端先收到 500，随后查询任务仍为 <code>todo</code>，状态变更记录仍为空。如果只验证 500，更新被错误提交也可能漏查。进入 <code>examples/go/learning-api</code> 可运行 <code>go test -run &#39;^TestStatusRollback$&#39; -count=1</code>。<a href="/programming/go/plus/practice/api#test">项目测试入口</a></p></details><h2 id="evidence" tabindex="-1">用项目证据组织面试回答 <a class="header-anchor" href="#evidence" aria-label="Permalink to &quot;用项目证据组织面试回答 {#evidence}&quot;">​</a></h2><p>选一个问题，按“结论 → 适用条件 → 最小实验 → 失败情形 → 项目中的验证”回答。自测标准是能预测输出、能解释错误结果、能指出验证位置；只记住术语不算通过。答错时回到同一正文，不另抄一份答案笔记。</p><p>四题完成后可以选一个综合问题。要证明工作者全部退出，检查返回时的活动计数和触发过的失败路径；要说明一次性能优化，给出相同输入、环境与统计口径的前后对照。可分别沿<a href="/programming/go/plus/practice/concurrency#verification">并发退出测试</a>与<a href="/programming/go/plus/practice/performance#decision">性能实验</a>核对证据。</p><p>需要扩大范围时，按<a href="/programming/go/pro/interview/golang-interview">面试主题目录</a>选择专题，或直接回答<a href="/programming/go/pro/interview/golang-interview#_28-高频面试快问快答">60 道快问快答</a>中的一组。</p><p>核对依据与完整示例在上述共用正文；语义依据：<a href="https://go.dev/ref/spec" target="_blank" rel="noopener noreferrer">Go 规范</a>、<a href="https://pkg.go.dev/context" target="_blank" rel="noopener noreferrer">context</a>、<a href="https://go.dev/doc/database/execute-transactions" target="_blank" rel="noopener noreferrer">database/sql 事务</a>。</p>',19)])])}const u=a(n,[["render",t]]);export{m as __pageData,u as default};
